# encode test grid from visual description
rows = [[4]*24 for _ in range(30)]
# top object A rows 2-6 cols 9-15
for c in range(9,16): rows[2][c]=7; rows[6][c]=7
for r in range(3,6):
    for c in [9,12,15]: rows[r][c]=7
    for c in [10,11,13,14]: rows[r][c]=3
# object B rows 1-4 cols 19-22
for c in range(19,23): rows[1][c]=7; rows[4][c]=7
for r in [2,3]:
    rows[r][19]=7; rows[r][22]=7
    rows[r][20]=rows[r][21]=3
# canvas 7 r13-20 base, side 3
for r in range(13,21):
    for c in range(24): rows[r][c]=7
    rows[r][0]=rows[r][23]=3
# separators unchanged r21
# canvas 3 r22-27 with 9 sides
for r in range(22,28):
    for c in range(24): rows[r][c]=3
    rows[r][0]=rows[r][23]=9
# apply each connected component of target color source as falling mask into target panel
from collections import deque
for color, panel_top, panel_bottom, outcolor in [(7,13,20,3),(3,22,27,9)]:
    seen=set(); comps=[]
    for r in range(10):
      for c in range(24):
        if rows[r][c]==color and (r,c) not in seen:
          q=[(r,c)]; seen.add((r,c)); comp=[]
          while q:
            x,y=q.pop(); comp.append((x,y))
            for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
              nx,ny=x+dx,y+dy
              if 0<=nx<10 and 0<=ny<24 and rows[nx][ny]==color and (nx,ny) not in seen:
                seen.add((nx,ny)); q.append((nx,ny))
          comps.append(comp)
    print(color,[(min(r for r,c in co),max(r for r,c in co),min(c for r,c in co),max(c for r,c in co),len(co)) for co in comps])
    for comp in comps:
      maxr=max(r for r,c in comp)
      delta=panel_bottom-maxr
      for r,c in comp:
        rr=r+delta
        # panel itself, avoid borders
        if panel_top<=rr<=panel_bottom and 0<c<23:
          rows[rr][c]=outcolor
print('\n'.join(' '.join(map(str,row)) for row in rows))
